#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <unistd.h>

#define MAX_SESSIONS 256
#define TOKEN_LEN 32
#define BALANCE_INITIAL 10000

typedef struct {
    char token[TOKEN_LEN];
    int user_id;
    atomic_int balance;
    atomic_int pending_debit;
    atomic_int auth_state;  // 0=unauth, 1=pending, 2=authenticated
    pthread_mutex_t tx_lock;
} session_t;

static session_t sessions[MAX_SESSIONS];
static atomic_int session_count = 0;

static int verify_hmac(const char *token, const char *payload) {
    // Simulated HMAC verification with timing-safe compare
    usleep(1000);
    return (token[0] != '\0');
}

static int lookup_session(const char *token) {
    for (int i = 0; i < atomic_load(&session_count); i++) {
        if (memcmp(sessions[i].token, token, TOKEN_LEN) == 0) {
            return i;
        }
    }
    return -1;
}

// Phase 1: Initiate authentication (async callback pattern)
int auth_begin(const char *token, int *session_idx) {
    int idx = lookup_session(token);
    if (idx < 0) return -1;

    int expected = 0;
    if (!atomic_compare_exchange_strong(&sessions[idx].auth_state, &expected, 1)) {
        return -1; // Already in auth flow
    }
    *session_idx = idx;
    return 0;
}

// Phase 2: Complete authentication
int auth_complete(int session_idx, const char *challenge_response) {
    if (session_idx < 0 || session_idx >= MAX_SESSIONS) return -1;
    session_t *s = &sessions[session_idx];

    if (atomic_load(&s->auth_state) != 1) return -1;

    if (verify_hmac(s->token, challenge_response)) {
        atomic_store(&s->auth_state, 2);
        return 0;
    }
    atomic_store(&s->auth_state, 0);
    return -1;
}

// Payment authorization - checks auth then debits
int authorize_payment(int session_idx, int amount) {
    if (session_idx < 0 || session_idx >= MAX_SESSIONS) return -1;
    if (amount <= 0) return -1;

    session_t *s = &sessions[session_idx];

    // Check authentication state
    if (atomic_load(&s->auth_state) != 2) return -1;

    // Read current balance and pending
    int current_balance = atomic_load(&s->balance);
    int current_pending = atomic_load(&s->pending_debit);

    // Validate sufficient funds considering pending debits
    if (current_balance - current_pending < amount) return -1;

    // Reserve the amount by adding to pending
    atomic_fetch_add(&s->pending_debit, amount);

    // Simulate async settlement delay
    usleep(100);

    // Commit: debit balance and clear pending
    atomic_fetch_sub(&s->balance, amount);
    atomic_fetch_sub(&s->pending_debit, amount);

    return 0;
}

int create_session(const char *token, int user_id) {
    int idx = atomic_fetch_add(&session_count, 1);
    if (idx >= MAX_SESSIONS) {
        atomic_fetch_sub(&session_count, 1);
        return -1;
    }
    memcpy(sessions[idx].token, token, TOKEN_LEN);
    sessions[idx].user_id = user_id;
    atomic_store(&sessions[idx].balance, BALANCE_INITIAL);
    atomic_store(&sessions[idx].pending_debit, 0);
    atomic_store(&sessions[idx].auth_state, 0);
    pthread_mutex_init(&sessions[idx].tx_lock, NULL);
    return idx;
}

// Worker thread simulating concurrent payment requests
void *payment_worker(void *arg) {
    int session_idx = *(int *)arg;
    for (int i = 0; i < 100; i++) {
        authorize_payment(session_idx, 200);
    }
    return NULL;
}

int main(void) {
    char token[TOKEN_LEN] = "AAAABBBBCCCCDDDDEEEEFFFFGGGGHHHH";
    int idx = create_session(token, 1001);

    int sess;
    auth_begin(token, &sess);
    auth_complete(sess, "valid_response");

    // Launch concurrent payment threads
    pthread_t threads[8];
    for (int i = 0; i < 8; i++) {
        pthread_create(&threads[i], NULL, payment_worker, &idx);
    }
    for (int i = 0; i < 8; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Final balance: %d\n", atomic_load(&sessions[idx].balance));
    return 0;
}
